// Kenali jenis masukan dari update Telegram dan normalkan jadi satu bentuk.
//
// Dua sumber yang didukung:
//   - audio  : voice note, file audio, video note, atau document ber-mime audio/video
//   - youtube: pesan teks (atau caption) yang mengandung link video YouTube
//
// Field `source` yang dihasilkan di sini ikut mengalir sampai ke tahap koreksi
// dan ringkasan, karena prompt-nya berbeda per sumber — kamus istilah bisnis
// hanya masuk akal untuk rekaman rapat, bukan untuk video orang lain.
const update = $input.first().json;
const message = update.message ?? update.channel_post ?? update;

const candidates = [
  ['voice', message.voice],
  ['audio', message.audio],
  ['video_note', message.video_note],
];

let kind = null;
let media = null;
for (const [name, value] of candidates) {
  if (value && value.file_id) {
    kind = name;
    media = value;
    break;
  }
}

if (!media && message.document?.file_id) {
  const mime = String(message.document.mime_type ?? '');
  if (/^(audio|video)\//.test(mime)) {
    kind = 'document';
    media = message.document;
  }
}

// --- deteksi link YouTube ------------------------------------------------
// Sengaja longgar: yang penting menangkap niat "ini link YouTube". Validasi
// sesungguhnya dilakukan yt-service, yang bisa membedakan playlist, channel,
// dan video tunggal dengan benar.
const text = `${message.text ?? ''} ${message.caption ?? ''}`.trim();
const YOUTUBE_LINK = /https?:\/\/(?:www\.|m\.|music\.)?(?:youtube\.com|youtu\.be)\/\S+/i;

const linkMatch = media ? null : text.match(YOUTUBE_LINK);
// Tanda baca di ujung kalimat ikut tertangkap \S+ — dibuang supaya URL bersih.
const youtubeUrl = linkMatch ? linkMatch[0].replace(/[.,;:!?)\]]+$/, '') : '';

const chatId = String(message.chat?.id ?? '');
// Hadir hanya kalau pesan dikirim di dalam topic grup forum; dipakai supaya
// balasan bot ikut masuk ke topic yang sama, bukan ke topic General.
const threadId = message.message_thread_id ?? undefined;
const sentAt = message.date ? new Date(message.date * 1000).toISOString() : new Date().toISOString();

const hasAudio = Boolean(media);
const hasYoutube = Boolean(youtubeUrl);

return [
  {
    json: {
      has_audio: hasAudio,
      has_youtube: hasYoutube,
      source: hasAudio ? 'voice' : hasYoutube ? 'youtube' : 'unknown',
      youtube_url: youtubeUrl,
      kind,
      chat_id: chatId,
      thread_id: threadId,
      message_id: message.message_id ?? null,
      from: message.from?.first_name ?? '',
      caption: String(message.caption ?? '').trim(),
      sent_at: sentAt,
      file_id: media?.file_id ?? '',
      file_name: media?.file_name ?? '',
      mime_type: media?.mime_type ?? '',
      file_size: Number(media?.file_size ?? 0),
      duration_sec: Number(media?.duration ?? 0),
    },
  },
];

// Susun body request ke yt-service.
// URL-nya berasal dari pesan Telegram — input bebas — jadi dirakit sebagai
// objek lalu di-JSON.stringify() di sini dan dikirim sebagai Raw body, sama
// seperti body LLM. Tanda kutip di URL tidak akan pernah merusak strukturnya.
const config = $('Config').first().json;
const source = $input.first().json;

const body = { url: String(source.youtube_url ?? '').trim() };

return [
  {
    json: {
      ...source,
      yt_url: `${String(config.yt_service_base_url).replace(/\/+$/, '')}/youtube/prepare`,
      body: JSON.stringify(body),
    },
  },
];

// Terjemahkan balasan yt-service jadi keputusan lanjut/berhenti.
//
// Node "YouTube: Prepare" sengaja memakai neverError + fullResponse +
// continueRegularOutput, jadi SEMUA kemungkinan bermuara ke sini sebagai satu
// item biasa: sukses, error HTTP dengan kode dari service, dan gagal terhubung
// karena PC mati. Satu tempat untuk memutuskan, bukan tiga cabang terpisah.
//
// Kode error dari yt-service diterjemahkan jadi kalimat yang memberi tahu Rizky
// apa yang harus dilakukan — tanpa ini semua kegagalan terlihat sama.
const previous = $('Build YouTube Request').first().json;
const response = $input.first().json ?? {};

const PESAN = {
  INVALID_URL: ['Link tidak dikenali', 'Itu bukan link video YouTube. Kirim link satu video ya.'],
  UNSUPPORTED_URL: ['Bukan video tunggal', 'Playlist dan channel belum didukung — kirim link satu video.'],
  LIVE_NOT_SUPPORTED: ['Masih siaran langsung', 'Tunggu siarannya selesai dulu, baru kirim ulang linknya.'],
  TOO_LONG: ['Video terlalu panjang', 'Batasnya 4 jam. Kalau perlu, potong dulu bagian yang mau diringkas.'],
  DURATION_UNKNOWN: ['Durasi tidak terbaca', 'Kemungkinan premiere atau siaran yang belum selesai.'],
  VIDEO_UNAVAILABLE: ['Video tidak tersedia', 'Videonya privat, sudah dihapus, atau dibatasi wilayah.'],
  BOT_CHECK: ['YouTube minta verifikasi', 'YouTube menandai unduhan ini sebagai bot. Perlu pasang cookies di yt-service.'],
  DOWNLOAD_FAILED: ['Gagal mengunduh video', 'Coba kirim ulang linknya sebentar lagi.'],
  TRANSCODE_FAILED: ['Gagal menyiapkan audio', 'Konversi audio di PC gagal. Cek log yt-service.'],
  STORAGE_FULL: ['Disk PC penuh', 'Kosongkan ruang di PC dulu, lalu kirim ulang.'],
  UNAUTHORIZED: ['Kredensial yt-service salah', 'Token di n8n tidak cocok dengan SERVICE_TOKEN di .env PC.'],
};

const meta = {
  chat_id: previous.chat_id,
  thread_id: previous.thread_id,
  message_id: previous.message_id,
  sent_at: previous.sent_at,
  caption: previous.caption,
  source: 'youtube',
  youtube_url: previous.youtube_url,
};

function gagal(stage, message, detail) {
  return [
    {
      json: {
        ...meta,
        yt_ok: false,
        error_stage: stage,
        error_message: message,
        // Dibaca Build Error Message untuk ditampilkan sebagai <code>.
        error: detail ? { message: String(detail).slice(0, 300) } : undefined,
      },
    },
  ];
}

// Gagal terhubung sama sekali — item tidak punya statusCode, hanya error.
if (response.error && response.statusCode === undefined) {
  const detail = response.error?.message ?? response.error?.description ?? '';
  return gagal(
    'PC perekam tidak aktif',
    'yt-service tidak merespons. Pastikan PC menyala dan Tailscale tersambung.',
    detail,
  );
}

const status = Number(response.statusCode ?? 0);
// fullResponse membungkus isinya di `body`; kalau opsi itu mati, isinya di akar.
const body = response.body ?? response;

if (status !== 200 || body?.ok !== true) {
  const code = String(body?.code ?? 'UNKNOWN');
  const [stage, message] = PESAN[code] ?? [
    'Gagal memproses link YouTube',
    'Coba kirim ulang linknya. Kalau terus gagal, cek log yt-service di PC.',
  ];
  return gagal(stage, message, body?.message ?? `HTTP ${status}`);
}

return [
  {
    json: {
      ...meta,
      yt_ok: true,
      video_id: body.videoId ?? '',
      video_title: body.title ?? '',
      video_channel: body.channel ?? '',
      audio_url: body.audioUrl ?? '',
      // Durasi dari yt-service dipakai sebagai perkiraan awal; angka final
      // tetap diambil dari ffprobe di Prepare Audio.
      duration_sec: Number(body.durationSec ?? 0),
    },
  },
];

// Kabari Rizky bahwa videonya sudah dikenali dan sedang diproses.
//
// Video 1 jam butuh 5-8 menit sampai ringkasan datang. Tanpa kabar apa pun
// selama itu, "sedang jalan" dan "mati diam-diam" terlihat sama persis. Pesan
// ini sekalian jadi konfirmasi bahwa video yang diambil memang yang dimaksud.
const data = $input.first().json;

function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function formatDuration(seconds) {
  const total = Math.max(0, Math.round(Number(seconds) || 0));
  if (!total) return '';
  const hours = Math.floor(total / 3600);
  const minutes = Math.floor((total % 3600) / 60);
  if (hours) return `${hours} jam ${minutes} mnt`;
  return `${minutes || 1} mnt`;
}

const title = String(data.video_title ?? '').trim() || 'Video YouTube';
const bits = [data.video_channel, formatDuration(data.duration_sec)].filter(Boolean);

const lines = [`🎬 <b>${escapeHtml(title)}</b>`];
if (bits.length) lines.push(`<i>${escapeHtml(bits.join(' · '))}</i>`);
lines.push('', '<i>Sedang diproses — ringkasan menyusul beberapa menit lagi.</i>');

return [
  {
    json: {
      chat_id: data.chat_id,
      thread_id: data.thread_id,
      ack_text: lines.join('\n'),
    },
  },
];

// Gabungkan hasil transkripsi semua part audio kembali jadi satu teks.
// Node ini menerima item dari jalur Groq maupun jalur fallback OpenAI, jadi
// urutannya dipulihkan lewat index part-nya, bukan lewat urutan item.
const items = $input.all();
const rows = [];

for (let i = 0; i < items.length; i++) {
  const json = items[i].json ?? {};

  let index = i;
  try {
    const matched = $('Split Parts').itemMatching(i);
    const value = Number(matched?.json?.index);
    if (Number.isFinite(value)) index = value;
  } catch (error) {
    // Paired-item tidak bisa ditelusuri (mis. provider mengubah bentuk item) —
    // pakai urutan kedatangan sebagai perkiraan terbaik.
    index = i;
  }

  const text = typeof json.text === 'string' ? json.text : (json.transcript ?? '');
  rows.push({ index, text: String(text).trim() });
}

rows.sort((a, b) => a.index - b.index);

const transcriptRaw = rows
  .map((row) => row.text)
  .filter(Boolean)
  .join('\n\n')
  .trim();

const meta = $('Extract Input').first().json;

function pick(nodeName) {
  try {
    return $(nodeName).first().json ?? null;
  } catch (error) {
    // Node itu tidak berjalan di eksekusi ini (mis. sumbernya voice note).
    return null;
  }
}

const video = pick('Parse YouTube Prepare');
// Durasi dari ffprobe adalah yang paling bisa dipercaya, dan tersedia untuk
// kedua sumber. Metadata Telegram/YouTube dipakai kalau ffprobe tidak terbaca.
const prepared = pick('Prepare Audio');
const durationSec =
  Number(prepared?.durationSec ?? 0) || Number(video?.duration_sec ?? 0) || Number(meta.duration_sec ?? 0);

return [
  {
    json: {
      chat_id: meta.chat_id,
      thread_id: meta.thread_id,
      message_id: meta.message_id,
      sent_at: meta.sent_at,
      caption: meta.caption,
      source: meta.source ?? 'voice',
      video_title: video?.video_title ?? '',
      video_channel: video?.video_channel ?? '',
      video_url: meta.youtube_url ?? '',
      duration_sec: durationSec,
      part_count: rows.length,
      transcript_raw: transcriptRaw,
      has_transcript: transcriptRaw.length > 0,
    },
  },
];

// Susun body request LLM untuk koreksi istilah.
//
// Berbeda dengan tahap ringkasan yang memampatkan, tahap ini harus mengeluarkan
// SELURUH transkrip lagi sebagai output. Transkrip satu jam (±15 ribu token)
// akan menabrak plafon output model dan terpotong diam-diam. Jadi transkrip
// panjang dipecah dulu, dan tiap potongan dikoreksi terpisah.
//
// Node ini mengembalikan satu item per potongan; HTTP Request node di n8n
// otomatis berjalan sekali untuk tiap item, jadi tidak perlu loop manual.
//
// Transkrip adalah input bebas, jadi body-nya dirakit sebagai objek lalu
// di-JSON.stringify() di sini dan dikirim sebagai Raw body oleh HTTP Request node.
const PROMPT_TEMPLATE = "Kamu adalah editor transkrip Bahasa Indonesia.\n\n{{KONTEKS}}\n\nTugasmu HANYA memperbaiki hasil speech-to-text, bukan menulis ulang.\n\nATURAN WAJIB:\n1. Perbaiki typo, salah dengar, dan ejaan istilah/brand.\n2. Perbaiki tanda baca, kapitalisasi, dan pemenggalan kalimat agar mudah dibaca.\n3. Hapus filler yang tidak bermakna (eh, emm, anu, gitu ya) bila mengganggu, tapi JANGAN memadatkan isi.\n4. JANGAN mengubah makna, JANGAN menambah informasi baru, JANGAN menyimpulkan, JANGAN menerjemahkan.\n5. Kalau sebuah kata benar-benar tidak jelas, biarkan apa adanya — jangan menebak fakta.\n6. Pertahankan angka, nominal, tanggal, dan nama orang persis seperti aslinya.\n7. Pisahkan menjadi paragraf saat topik berganti.\n{{KAMUS}}\n\nFORMAT OUTPUT:\nBalas HANYA dengan teks transkrip yang sudah diperbaiki. Tanpa pembuka, tanpa penutup, tanpa penjelasan, tanpa tanda kutip pembungkus, tanpa blok kode.";
const GLOSSARY_BLOCK = "Brand & nama produk: Zaneva, Elyasr, Be.Syari, Oberbe, Muslimah Swimwear, Yaumiah\nIstilah bisnis: ROAS, ROI, HPP, omzet, margin, gross profit, net profit, cashflow, CPA, CPM, CTR, AOV, SKU, COD, closing, reseller, affiliate, endorse, marketplace, funnel, landing page, retargeting, budget harian, content plan, stock opname, pre-order, restock, supplier, invoice, purchase order, cash on delivery";

const config = $('Config').first().json;
const source = $input.first().json;
const transcript = String(source.transcript_raw ?? '').trim();

// Kamus istilah bisnis hanya masuk akal untuk rekaman Rizky sendiri. Untuk
// video orang lain, menyuntikkan "Zaneva/ROAS/HPP" justru membuat model
// "mengoreksi" kata yang sebenarnya sudah benar menjadi nama brand — kerusakan
// yang tidak akan terlihat karena hasilnya tetap terbaca wajar.
const isBisnis = source.source !== 'youtube';

// Judul video adalah teks dari orang lain yang masuk ke system prompt. Sudah
// dibersihkan di yt-service, dibersihkan lagi di sini sebagai lapis kedua.
const videoTitle = String(source.video_title ?? '')
  .replace(/[\r\n]+/g, ' ')
  .trim()
  .slice(0, 150);

const SYSTEM_PROMPT = PROMPT_TEMPLATE
  .replace(
    '{{KONTEKS}}',
    isBisnis
      ? 'Sumbernya rekaman rapat/brainstorm bisnis.'
      : `Sumbernya transkrip otomatis video YouTube${videoTitle ? ` berjudul "${videoTitle}"` : ''}. Topiknya bisa apa saja.`,
  )
  // Blok kamus dihilangkan sepenuhnya untuk sumber non-bisnis — bukan diisi
  // "tidak ada kamus", karena menyebut kamus kosong hanya membingungkan model.
  .replace(
    '{{KAMUS}}',
    isBisnis ? `\nKAMUS EJAAN (ini ejaan yang benar — pakai persis seperti ini):\n${GLOSSARY_BLOCK}` : '',
  )
  .trim();

// Batas karakter per potongan. 0 / kosong = jangan potong sama sekali.
const chunkChars = Math.max(0, Number(config.correction_chunk_chars ?? 9000) || 0);

/**
 * Potong teks di batas paling alami yang masih muat: paragraf dulu, lalu
 * kalimat, dan hanya kalau terpaksa dipotong di tengah. Tujuannya supaya tiap
 * potongan tetap bisa dibaca model sebagai satuan yang utuh.
 */
function splitTranscript(text, limit) {
  if (!limit || text.length <= limit) return text ? [text] : [];

  const chunks = [];
  let current = '';

  const flush = () => {
    const trimmed = current.trim();
    if (trimmed) chunks.push(trimmed);
    current = '';
  };

  // Coba sambung ke potongan berjalan; gagal kalau jadi melewati batas.
  const append = (piece, separator) => {
    const candidate = current ? current + separator + piece : piece;
    if (candidate.length > limit) return false;
    current = candidate;
    return true;
  };

  for (const paragraph of text.split(/\n{2,}/)) {
    const block = paragraph.trim();
    if (!block) continue;
    if (append(block, '\n\n')) continue;

    flush();
    if (block.length <= limit) {
      current = block;
      continue;
    }

    // Satu paragraf saja sudah kebesaran → turun ke batas kalimat.
    for (const sentence of block.match(/[^.!?\n]+[.!?]*\s*/g) ?? [block]) {
      const piece = sentence.trim();
      if (!piece) continue;
      if (append(piece, ' ')) continue;

      flush();
      if (piece.length <= limit) {
        current = piece;
        continue;
      }

      // Kalimat sangat panjang tanpa tanda baca (jarang, tapi Whisper bisa
      // menghasilkannya) → potong paksa daripada melewati batas.
      for (let i = 0; i < piece.length; i += limit) chunks.push(piece.slice(i, i + limit));
    }
  }
  flush();

  return chunks.length ? chunks : [text];
}

const split = splitTranscript(transcript, chunkChars);
// Selalu kembalikan minimal satu item supaya metadata tidak hilang dari alur.
const chunks = split.length ? split : [transcript];
const total = chunks.length;
const llmUrl = `${String(config.llm_base_url).replace(/\/+$/, '')}/chat/completions`;

return chunks.map((chunk, index) => {
  const messages = [{ role: 'system', content: SYSTEM_PROMPT }];

  if (total > 1) {
    // Tanpa instruksi ini model cenderung menambahkan "Berikut lanjutannya:"
    // atau catatan bahwa teksnya terpotong — dan itu ikut tergabung ke hasil.
    messages.push({
      role: 'system',
      content:
        `Ini potongan ke-${index + 1} dari ${total} sebuah transkrip panjang. ` +
        'Perbaiki potongan ini saja dan balas hanya isinya. Jangan menambah kalimat ' +
        'penghubung, pembuka, penutup, atau catatan bahwa teks ini terpotong. ' +
        'Wajar kalau potongan ini dimulai atau berakhir di tengah pembicaraan.',
    });
  }

  messages.push({ role: 'user', content: chunk });

  const body = {
    model: config.llm_model,
    temperature: Number(config.llm_temperature_correct ?? 0.1),
    messages,
  };

  return {
    json: {
      ...source,
      chunk_index: index,
      chunk_total: total,
      // Disimpan supaya Parse Correction bisa jatuh balik per potongan.
      chunk_text: chunk,
      llm_url: llmUrl,
      body: JSON.stringify(body),
    },
  };
});

// Ambil teks balasan LLM dari bentuk respons OpenAI-compatible, lalu susun
// kembali potongan-potongan transkrip jadi satu teks utuh.
//
// Node ini menerima satu item per potongan (lihat Build Correction Request) dan
// memasang dua pengaman:
//
// 1. Potongan yang gagal — atau yang balasannya jauh lebih pendek dari aslinya,
//    tanda balasannya kena plafon output model — dianggap tidak terpakai, dan
//    yang dipakai adalah teks mentah potongan itu. Lebih baik satu bagian tidak
//    terkoreksi daripada isinya hilang separuh tanpa ketahuan.
// 2. Node "LLM: Correct Terms" memakai continueRegularOutput, jadi item yang
//    error ikut masuk ke sini alih-alih menyalakan jalur error terpisah. Kalau
//    lewat jalur error, satu potongan gagal akan membuat jalur error dan jalur
//    sukses menyala bersamaan — dan Rizky menerima pesan error plus ringkasan.
const config = $('Config').first().json;
const requests = $('Build Correction Request');
const previous = requests.first().json;

const minRatio = Number(config.correction_min_ratio ?? 0.6);
// Koreksi memang memangkas filler ("eh", "anu", "gitu ya"), jadi teks pendek
// wajar menyusut banyak. Pemeriksaan rasio baru berarti untuk potongan yang
// cukup panjang — yaitu satu-satunya yang bisa kena plafon output.
const GUARD_MIN_CHARS = 2000;

function textOf(response) {
  const choice = response?.choices?.[0];
  const raw = choice?.message?.content ?? choice?.text ?? '';

  return (Array.isArray(raw) ? raw.map((part) => part?.text ?? '').join('') : String(raw))
    // Sebagian model membungkus jawaban dalam blok kode meski sudah dilarang.
    .replace(/^\s*```[a-z]*\s*\n?/i, '')
    .replace(/\n?```\s*$/i, '')
    .trim();
}

const items = $input.all();
const rows = [];
let failed = 0;

for (let i = 0; i < items.length; i++) {
  const response = items[i].json ?? {};

  let request = {};
  try {
    request = requests.itemMatching(i)?.json ?? {};
  } catch (error) {
    // Paired-item tidak bisa ditelusuri (mis. provider mengubah bentuk item) —
    // pakai urutan kedatangan sebagai perkiraan terbaik.
    request = {};
  }

  const parsedIndex = Number(request.chunk_index);
  const index = Number.isFinite(parsedIndex) ? parsedIndex : i;
  const original = String(request.chunk_text ?? previous.transcript_raw ?? '');
  const corrected = response.error ? '' : textOf(response);

  const truncated =
    original.length >= GUARD_MIN_CHARS && corrected.length < original.length * minRatio;
  const usable = corrected.length > 0 && !truncated;

  if (!usable) failed += 1;
  rows.push({ index, text: usable ? corrected : original });
}

rows.sort((a, b) => a.index - b.index);

const merged = rows
  .map((row) => row.text)
  .filter(Boolean)
  .join('\n\n')
  .trim();

const total = rows.length;

return [
  {
    json: {
      chat_id: previous.chat_id,
      thread_id: previous.thread_id,
      message_id: previous.message_id,
      sent_at: previous.sent_at,
      caption: previous.caption,
      // Ikut mengalir karena prompt ringkasan juga bergantung pada sumbernya.
      source: previous.source,
      video_title: previous.video_title,
      video_channel: previous.video_channel,
      video_url: previous.video_url,
      duration_sec: previous.duration_sec,
      part_count: previous.part_count,
      transcript_raw: previous.transcript_raw,
      // Kalau semuanya gagal, lebih baik pakai transkrip mentah daripada gagal.
      transcript_corrected: merged || previous.transcript_raw,
      correction_applied: total > 0 && failed < total,
      correction_chunk_total: total,
      correction_chunk_failed: failed,
    },
  },
];

// Susun body request LLM untuk ringkasan + outline mind map.
// Node yang sama dipakai untuk percobaan pertama dan percobaan ulang; saat
// RETRY_MODE aktif, instruksi tambahan soal JSON valid ikut dikirim.
