    for (const child of Array.isArray(theme?.children) ? theme.children : []) {
      lines.push(`   ◦ ${escapeHtml(child?.title)}`);
    }
  }
}

if (!WITH_MINDMAP) {
  lines.push('', '<i>⚠️ Mind map gagal dibuat kali ini — ringkasan tetap dikirim.</i>');
}

let text = lines.join('\n').replace(/\n{3,}/g, '\n\n').trim();
if (text.length > TELEGRAM_LIMIT) {
  text = `${text.slice(0, TELEGRAM_LIMIT - 30).trim()}\n\n<i>… (dipotong)</i>`;
}

return [
  {
    json: {
      chat_id: data.chat_id ?? $('Extract Input').first().json.chat_id,
      thread_id: data.thread_id ?? $('Extract Input').first().json.thread_id,
      title: data.title ?? 'Catatan Suara',
      summary_text: text,
    },
  },
];

// Kirim transkrip bersih: sebagai pesan biasa kalau pendek, sebagai file .txt
// kalau panjang (batas pesan Telegram 4096 karakter).
const config = $('Config').first().json;
const data = $('Parse Correction').first().json;

const transcript = String(data.transcript_corrected ?? data.transcript_raw ?? '').trim();
const limit = Number(config.max_transcript_inline ?? 3000);
const chatId = data.chat_id ?? $('Extract Input').first().json.chat_id;
const threadId = data.thread_id ?? $('Extract Input').first().json.thread_id;

function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function stamp(iso) {
  const date = new Date(iso ?? Date.now());
  const valid = Number.isNaN(date.getTime()) ? new Date() : date;
  return valid.toISOString().slice(0, 16).replace('T', '-').replace(':', '');
}

if (transcript.length <= limit) {
  return [
    {
      json: {
        chat_id: chatId,
        thread_id: threadId,
        is_file: false,
        transcript_text: `📝 <b>Transkrip</b>\n\n${escapeHtml(transcript)}`,
      },
    },
  ];
}

const header = [
  data.title ? `Judul: ${data.title}` : null,
  `Tanggal: ${data.sent_at ?? ''}`,
  '',
  '',
].filter((line) => line !== null);

const content = `${header.join('\n')}${transcript}\n`;
const fileName = `transkrip-${stamp(data.sent_at)}.txt`;

return [
  {
    json: {
      chat_id: chatId,
      thread_id: threadId,
      is_file: true,
      file_name: fileName,
      transcript_text: '',
    },
    binary: {
      data: {
        data: Buffer.from(content, 'utf8').toString('base64'),
        mimeType: 'text/plain',
        fileName,
        fileExtension: 'txt',
      },
    },
  },
];

// Susun pesan error yang dikirim ke Telegram.
// Semua jalur error bertemu di sini; tahap & kalimat ramahnya sudah diisi oleh
// node "Stage: ..." tepat sebelum node ini.
const item = $input.first().json ?? {};

function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

const detail = String(
  item.error?.message ??
    item.error?.description ??
    item.error?.error ??
    (typeof item.error === 'string' ? item.error : '') ??
    item.message ??
    '',
).trim();

const lines = [
  `⚠️ <b>${escapeHtml(item.error_stage ?? 'Pemrosesan gagal')}</b>`,
  escapeHtml(item.error_message ?? 'Coba kirim ulang rekamannya ya.'),
];

if (detail) {
  lines.push('', `<code>${escapeHtml(detail.slice(0, 300))}</code>`);
}

let chatId = item.chat_id ?? '';
let threadId = item.thread_id;
if (!chatId) {
  try {
    chatId = $('Extract Input').first().json.chat_id;
    threadId = $('Extract Input').first().json.thread_id;
  } catch (error) {
    chatId = '';
  }
}

return [
  {
    json: {
      chat_id: chatId,
      thread_id: threadId,
      error_text: lines.join('\n'),
    },
  },
];
